  [1311015] = { "発動すると、$D1の間、最大体力の$N1%に等しいダメージを吸収するシールドを得ます。$D2の間Forbearanceを付与します。Forbearanceが有効な間は使用できません。", "$N1のダメージを吸収します。", 0xc9efc399, 0x4e7b6db5, "uu" },
