  [1311085] = { "Hammer of Wrathの詠唱時間を$N1秒短縮し、Righteous Furyが有効でない間、生み出すすべての脅威を$N2%減少させます。", nil, 0x89a8b73c, nil, "um" },
  [1311087] = { "Holy Strikeアビリティのダメージを$N1%増加させ、対象にかかっているすべてのJudgement効果を更新するようにします。", nil, 0x01026fd3, nil, "um" },
  [1311590] = { "対象に$D1の間Light's Vigilを付与します。その対象に次に唱えるHoly Shockはクールダウンが発生せず、敵対象には$N2のHolyダメージを与えてLight's Vigilのマナコストの$N3%を返還し、味方対象にはそのパーティーを$N4回復させます。パラディンが有効にできるLight's Vigilは、パーティーごとに一つだけです。", nil, 0x37ff53a6, nil, "um" },
  [1311595] = { "対象に$D1の間Light's Vigilを付与します。その対象に次に唱えるHoly Shockはクールダウンが発生せず、敵対象には$N2のHolyダメージを与えてLight's Vigilのマナコストの$N3%を返還し、味方対象にはそのパーティーを$N4回復させます。パラディンが有効にできるLight's Vigilは、パーティーごとに一つだけです。", nil, 0x6f9f0ddc, nil, "um" },
  [1311606] = { "Holyのエネルギーで対象を撃ち、敵には$N1のHolyダメージを与え、味方は$N2回復します。", nil, 0xd6df89f7, nil, "um" },
  [1311649] = { "$D1の間、パラディンを神聖な怒りで満たし、近接攻撃がさらに$N2のHolyダメージを与えるようにします。盾を装備している間は、攻撃するたびに与えたHolyダメージの$N3%に等しいダメージを吸収するシールドも得ます。パラディンが一度に有効にできるSealは一つだけです。\n\nこのSealのエネルギーを解き放つと、敵に$N4のHolyダメージを与え、$D2の間、対象を挑発して自分を攻撃させます。", "近接攻撃が$N1の追加Holyダメージを与えます。", 0xca4247f8, 0x85b1a96e, "uu" },
  [1311656] = { "$D1の間、パラディンを神聖な怒りで満たし、近接攻撃がさらに$N2のHolyダメージを与えるようにします。盾を装備している間は、攻撃するたびに与えたHolyダメージの$N3%に等しいダメージを吸収するシールドも得ます。パラディンが一度に有効にできるSealは一つだけです。\n\nこのSealのエネルギーを解き放つと、敵に$N4のHolyダメージを与え、$D2の間、対象を挑発して自分を攻撃させます。", "近接攻撃が$N1の追加Holyダメージを与えます。", 0x6cbc44c6, 0x1ff00211, "uu" },
  [1311676] = { "$D1の間、対象に呪いをかけ、Magic耐性を$N2低下させ、受けるMagicダメージを$N3%増加させます。1体の対象に対して、各ウォーロックがかけられるCurseは1つだけです。", "Magic耐性が$N1低下します。受けるMagicダメージが$N2%増加します。", 0x68afc919, 0x96faf3fe, "uu" },
